  assert.ok(Math.abs(ball.x - 400) < 1, `x=${ball.x}`);
  assert.ok(Math.abs(ball.y - 300) < 1, 'gravity does not pull a held ball');
  world.release(12 / 60);
  assert.ok(ball.vx > 700 && ball.vx <= MAX_SPEED, `throw vx=${ball.vx}`);
  assert.ok(ball.invMass > 0, 'released ball is movable again');
});

test('releasing after holding still drops the ball gently', () => {
  const world = new World({ width: 1000, height: 600, rng: seeded() });
  const ball = world.addBall({ x: 200, y: 300, r: 20 });
  world.grab(ball, 200, 300, 0);
  world.dragTo(400, 300, 0.05);
  world.release(1); // pointer idle for almost a second
  assert.equal(ball.vx, 0);
});

test('resizing pulls balls back inside', () => {
  const world = new World({ width: 1000, height: 600, rng: seeded() });
  const ball = world.addBall({ x: 950, y: 550, r: 20 });
  world.setSize(400, 300);
  assert.equal(ball.x, 380);
  assert.equal(ball.y, 280);
});

test('advance runs fixed steps and caps catch-up after a long pause', () => {
  const world = new World({ width: 800, height: 600, rng: seeded() });
  assert.equal(world.advance(FIXED_DT * 4 + 1e-9), 4);
  assert.ok(world.advance(10) <= Math.ceil(0.1 / FIXED_DT));
});

test('reset spawns the starting count of balls inside the world', () => {
  const world = new World({ width: 800, height: 600, settings: { startCount: 15 }, rng: seeded() });
  world.reset();
  assert.equal(world.balls.length, 15);
});

test('ballAt finds the topmost ball under a point', () => {
  const world = new World({ width: 800, height: 600, rng: seeded() });
  world.addBall({ x: 100, y: 100, r: 30 });
  const top = world.addBall({ x: 110, y: 100, r: 30 });
  assert.equal(world.ballAt(105, 100), top);
  assert.equal(world.ballAt(500, 500), null);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  DEFAULTS,
  LIMITS,
  GRAVITY_PRESETS,
  clampSetting,
  settingsFromHash,
  settingsToHash,
  presetForGravity,
} from '../site/js/settings.js';

test('defaults to Moon gravity', () => {
  assert.equal(DEFAULTS.gravity, 1.62);
  assert.equal(presetForGravity(DEFAULTS.gravity)?.id, 'moon');
});

test('every default and preset is within its limits', () => {
  for (const [key, value] of Object.entries(DEFAULTS)) {
    assert.ok(value >= LIMITS[key].min && value <= LIMITS[key].max, key);
  }
  for (const p of GRAVITY_PRESETS) {
    assert.ok(p.gravity >= LIMITS.gravity.min && p.gravity <= LIMITS.gravity.max, p.id);
  }
});

test('clampSetting clamps, snaps to step, and rejects junk', () => {
  assert.equal(clampSetting('gravity', 99), 25);
  assert.equal(clampSetting('gravity', -3), 0);
  assert.equal(clampSetting('gravity', '3.714'), 3.71);
  assert.equal(clampSetting('startCount', 7.6), 8);
  assert.equal(clampSetting('bounciness', 'abc'), DEFAULTS.bounciness);
  assert.equal(clampSetting('bounciness', ''), DEFAULTS.bounciness);
  assert.equal(clampSetting('ballSize', Infinity), DEFAULTS.ballSize);
});

test('the default configuration has an empty hash', () => {
  assert.equal(settingsToHash(DEFAULTS), '');
  assert.deepEqual(settingsFromHash(''), DEFAULTS);
});

test('settings round-trip through the URL hash', () => {
  const custom = { gravity: 9.81, bounciness: 0.9, airDrag: 0.1, ballSize: 30, startCount: 40 };
  const hash = settingsToHash(custom);
  assert.equal(hash, '#g=9.81&e=0.9&d=0.1&s=30&n=40');
  assert.deepEqual(settingsFromHash(hash), custom);
});

test('a hash only encodes what differs from the defaults', () => {
  assert.equal(settingsToHash({ ...DEFAULTS, gravity: 24.79 }), '#g=24.79');
});

test('hostile or malformed hashes fall back to safe values', () => {
  const s = settingsFromHash('#g=1e9&e=-5&n=NaN&s=<script>&x=1');
  assert.equal(s.gravity, LIMITS.gravity.max);
  assert.equal(s.bounciness, LIMITS.bounciness.min);
  assert.equal(s.startCount, DEFAULTS.startCount);
  assert.equal(s.ballSize, DEFAULTS.ballSize);
  assert.ok(!('x' in s));
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { COLOR_FAMILIES, PALETTE, hexToRgb, randomColor } from '../site/js/palette.js';

test('four base colors with 10 shades each, 40 in total', () => {
  assert.deepEqual(
    COLOR_FAMILIES.map((f) => f.base),
    ['#F25022', '#7FBA00', '#00A4EF', '#FFB900'],
  );
  for (const f of COLOR_FAMILIES) assert.equal(f.shades.length, 10, f.name);
  assert.equal(PALETTE.length, 40);
});

test('every shade is a valid, unique hex color', () => {
  for (const c of PALETTE) assert.match(c, /^#[0-9A-F]{6}$/);
  assert.equal(new Set(PALETTE).size, 40);
});

test('every shade is within 5% of its base color on each channel', () => {
  for (const f of COLOR_FAMILIES) {
    const base = hexToRgb(f.base);
    for (const shade of f.shades) {
      hexToRgb(shade).forEach((v, i) => {
        const allowed = Math.max(1, base[i] * 0.05) + 0.5; // +0.5 for rounding to integers
        assert.ok(Math.abs(v - base[i]) <= allowed, `${f.name} ${shade} channel ${i}: ${v} vs ${base[i]}`);
      });
    }
  }
});

test('randomColor always returns a palette entry', () => {
  assert.equal(randomColor(() => 0), PALETTE[0]);
  assert.equal(randomColor(() => 0.999999), PALETTE[39]);
  for (let i = 0; i < 200; i++) assert.ok(PALETTE.includes(randomColor()));
});

