  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}
.field-head label { font-weight: 500; }
.field-head output {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
