input[type="range"] {
  width: 100%;
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}
.button-row .btn { flex: 1 1 0; }
.group-actions .button-row { margin-top: 0; }
.group-actions .btn-link { margin-top: 10px; }

